let cards=[],metadata={},view='decks',edit=null,editTab='cards',query='',civ='',costFilter='',typeFilter='',page=0,opponentCategory='すべて',opponentQuery='',selectedOpp='practice-wu',mode='auto',count=1000,first='random',allOpp=false,practice=true,activeRun=null,running=null,worker=null,comparisonId=null,battle=null,battleUndo=[],battleTimer=null,selectedHand=null,photo=null,ocrWorker=null,ocrPromise=null,ocrBusy=false,replayData=null,replayIndex=0,replayTimer=null;
