function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function showDialog(title,html,footer=''){dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="閉じる">${icon('close')}</button></div><div class="dialog-content">${html}</div>${footer?`<div class="dialog-actions">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();}
