function shell(html){root.innerHTML=`<header class="app-header"><button class="brand" data-action="nav" data-view="decks"><img src="assets/icon.svg" alt="" class="brand-symbol"><span><strong>デッキラボ</strong><small>DUEL MASTERS · DECK LAB</small></span></button><div class="header-meta"><span><i class="dot-live"></i>この端末に保存</span><span class="mobile-hide">紙のデュエマ / オリジナル</span><button class="icon-btn" data-action="about" aria-label="対応範囲とルール" style="color:#c4d2db">${icon('help')}</button></div></header><div class="app-shell"><aside class="sidebar">${navItem('decks','マイデッキ')}${navItem('battle','対戦する')}${navItem('analysis','分析・比較')}${navItem('history','対戦履歴')}<div class="sidebar-foot"><span class="version-pill">EARLY ACCESS · v0.1</span><p>組む。試す。もっと強く。</p><p>対応カード ${cards.length}種類<br>公式ルールを基にした練習版</p><button class="details-link" data-action="about">対応範囲・データについて ${icon('chevron',11)}</button></div></aside><main class="main" id="main">${!storageOK?'<div class="data-warning">保存できませんでした。デッキを書き出して保管してください。</div>':''}${html}</main></div><nav class="bottom-nav" aria-label="メインメニュー">${navItem('decks','デッキ')}${navItem('battle','対戦')}${navItem('analysis','分析')}${navItem('history','履歴')}</nav>`;}
