function art(id,{mini=false}={}){const c=card(id);if(!c)return '';return `<span class="art-card" style="--civ-color:${color[c.civ]};--art-pos:${pos[c.civ]}%"><span class="art"></span><span class="cost">${c.cost}</span>${c.trigger?'<span class="trigger-mark">S・T</span>':''}<span class="card-bottom">${esc(c.name)}<span class="power">${c.power?fmt(c.power):'SPELL'}</span></span></span>`;}
