function dots(d){const colors=[...new Set(d.cards.map(r=>card(r.id)?.civ).filter(Boolean))];return `<span class="color-dots">${colors.map(c=>`<span class="civ-dot" style="background:${color[c]}" title="${c}"></span>`).join('')}</span>`;}
