function deckCard(d){return `<article class="deck-card ${saved.selected===d.id?'selected':''}"><div class="deck-banner"><div class="art-bg" style="background-position:${pos[card(d.cards[0]?.id)?.civ]||0}% 30%"></div><div class="deck-banner-top"><span class="badge">オリジナル</span><span class="badge ${saved.selected===d.id?'green':''}">${saved.selected===d.id?'使用中':'端末に保存'}</span></div><div class="deck-banner-bottom">MY DECK / ${fmt(sum(d))} CARDS</div></div><div class="deck-body"><div class="row spread"><h2>${esc(d.name)}</h2><button class="icon-btn" data-action="deck-menu" data-id="${esc(d.id)}" aria-label="デッキの操作">${icon('settings',18)}</button></div><div class="deck-meta">${dots(d)}<span>${sum(d)}枚</span><span>·</span><span>${d.cards.length}種類</span><span>·</span><span>${validateDeck(d).length?'編集中':'対戦可能'}</span></div><div class="deck-actions"><button class="btn primary" data-action="use-deck" data-id="${esc(d.id)}">${icon('battle',15)}このデッキで対戦</button><button class="btn" data-action="edit" data-id="${esc(d.id)}">${icon('edit',14)}編集</button></div></div></article>`;}
function renderDecks(){const total=saved.history.reduce((s,r)=>s+r.stats.total,0);shell(`${pageHead('マイデッキ','自分だけの構成をつくって、対戦で確かめよう。',`<button class="btn primary" data-action="new-deck">${icon('plus',16)}デッキを作成</button>`,'YOUR COLLECTION')}<div class="home-stats"><div class="stat-tile"><span class="stat-icon">${icon('decks',20)}</span><div><small>保存したデッキ</small><strong>${saved.decks.length}<small>デッキ</small></strong></div></div><div class="stat-tile"><span class="stat-icon">${icon('battle',20)}</span><div><small>シミュレーション</small><strong>${fmt(total)}<small>戦</small></strong></div></div><div class="stat-tile"><span class="stat-icon">${icon('history',20)}</span><div><small>分析レポート</small><strong>${saved.history.length}<small>件</small></strong></div></div></div><div class="row spread mb16"><h2>デッキ一覧 <span class="count-chip">${saved.decks.length}</span></h2><button class="details-link" data-action="import-text">${icon('upload',13)} リストを読み込む</button></div><div class="deck-grid">${saved.decks.map(deckCard).join('')}<button class="empty-card" data-action="new-deck"><span class="round-icon">${icon('plus',25)}</span><h3>新しいデッキを作る</h3><p>カード一覧・写真・スクリーンショットから登録</p></button></div><div class="mt24">${notice(`<strong>最初の1戦は、ここから。</strong><br>マイデッキ01は練習用の構成です。編集して自分のデッキに変えたり、そのまま対戦を試せます。<br>現在は初期カード${cards.length}種類に対応。全カード・環境デッキへの対応は準備中です。`)}</div><p class="art-disclaimer">カードのイラストは識別補助用のオリジナル画像です。実際のカード画像ではありません。</p>`);}
function curve(d){const values=Array(9).fill(0);for(const r of d.cards){const c=card(r.id);if(c)values[Math.min(c.cost,8)]+=r.count;}const max=Math.max(...values,1);return `<div class="curve">${values.map((n,i)=>`<div class="curve-col"><div class="curve-bar" style="height:${n/max*53}px"><span>${n||''}</span></div><small>${i===8?'8+':i}</small></div>`).join('')}</div>`;}
