function renderEditor(){
 const errors=validateDeck(edit),total=sum(edit);const filtered=cards.filter(c=>(!query||norm(c.name+c.race+c.text).includes(norm(query)))&&(!civ||c.civ===civ)&&(!costFilter||(costFilter==='5+'?c.cost>=5:c.cost===Number(costFilter)))&&(!typeFilter||c.type===typeFilter));const pages=Math.ceil(filtered.length/18)||1;page=Math.min(page,pages-1);const shown=filtered.slice(page*18,page*18+18);
 const catalogueHTML=`<div class="search-wrap">${icon('search',17)}<input class="field" id="card-search" placeholder="カード名・種族・能力で検索" value="${esc(query)}" aria-label="カード検索"></div><div class="filters mt16"><button class="filter ${!civ?'active':''}" data-action="civ" data-civ="">すべて</button>${Object.keys(color).map(c=>`<button class="filter ${civ===c?'active':''}" data-action="civ" data-civ="${c}"><span class="civ-dot" style="background:${color[c]}"></span>${c}</button>`).join('')}<select id="cost-filter" class="filter-select" aria-label="コスト"><option value="">コスト</option>${[1,2,3,4,'5+'].map(n=>`<option ${costFilter===String(n)?'selected':''}>${n}</option>`).join('')}</select><select id="type-filter" class="filter-select" aria-label="種類"><option value="">種類</option><option value="creature" ${typeFilter==='creature'?'selected':''}>クリーチャー</option><option value="spell" ${typeFilter==='spell'?'selected':''}>呪文</option></select></div><div class="result-count">${filtered.length}種類 · 対応済みカードのみ表示</div><div class="card-grid">${shown.map(c=>{const n=edit.cards.find(r=>r.id===c.id)?.count||0;return `<div class="catalog-card ${n?'included':''}"><button class="card-art-button" data-action="card-detail" data-id="${c.id}" aria-label="${esc(c.name)}の詳細">${art(c.id)}</button><div class="card-name">${esc(c.name)}</div><div class="stepper"><button data-action="quantity" data-id="${c.id}" data-delta="-1" ${n?'':'disabled'} aria-label="${esc(c.name)}を1枚減らす">−</button><span>${n}枚</span><button class="add" data-action="quantity" data-id="${c.id}" data-delta="1" ${n>=c.limit||total>=40?'disabled':''} aria-label="${esc(c.name)}を1枚追加">＋</button></div></div>`;}).join('')}</div>${!shown.length?'<div class="empty-state"><p>該当するカードがありません。現在の対応は初期44種類です。</p></div>':''}<div class="pagination"><button class="btn sm" data-action="page" data-delta="-1" ${page===0?'disabled':''}>前へ</button><span>${page+1} / ${pages}</span><button class="btn sm" data-action="page" data-delta="1" ${page+1>=pages?'disabled':''}>次へ</button></div>`;
 shell(`${pageHead('デッキ作成','カードを選んで、40枚の構成をつくろう。',`<div class="toolbar-actions"><button class="btn" data-action="nav" data-view="decks">${icon('back',14)}戻る</button><button class="btn" data-action="import-text">${icon('upload',14)}リスト入力</button></div>`,'BUILD YOUR DECK')}<div class="editor-toolbar"><input class="field" id="deck-name" aria-label="デッキ名" value="${esc(edit.name)}" maxlength="50"><span class="badge">${icon('lock',11)}この端末のみ</span><span class="badge mobile-hide">オリジナル</span></div><div class="editor-layout"><section class="panel"><div class="tabs dark-active mb16"><button data-action="editor-tab" data-tab="cards" class="${editTab==='cards'?'active':''}">カード一覧</button><button data-action="editor-tab" data-tab="photo" class="${editTab==='photo'?'active':''}">${icon('camera',14)} 写真から登録</button></div>${editTab==='cards'?catalogueHTML:photoHTML()}</section><aside class="panel editor-summary"><div class="desktop-summary-label eyebrow mb16">YOUR DECK</div><div class="summary-count-row"><div class="row spread"><div><div class="small">デッキの枚数</div><div class="count-big ${total===40?'green':''}">${total}<small>/ 40 枚</small></div></div><span class="badge green desktop-summary-label">${total===40?'構築OK':`あと${40-total}枚`}</span></div><button class="btn primary full mt16 summary-save" data-action="save-deck" ${errors.length?'disabled':''}>${icon('save',15)}デッキを保存</button></div><div class="curve-section mt24"><h3>コストバランス</h3>${curve(edit)}</div><div class="deck-list">${edit.cards.filter(r=>r.count).sort((a,b)=>card(a.id).cost-card(b.id).cost).map(r=>`<div class="deck-list-row"><span class="cost-small">${card(r.id).cost}</span><span class="grow">${esc(card(r.id).name)}</span><strong>${r.count}</strong><button class="icon-btn" data-action="quantity" data-id="${r.id}" data-delta="-1" aria-label="1枚減らす">−</button></div>`).join('')}</div><div class="summary-end mt16"><small>${errors.length?esc(errors[0]):'対応カード・枚数を確認済みです。'}</small></div></aside></div>`);
}
function photoHTML(){return `<input type="file" class="file-input" id="photo-file" accept="image/*"><input type="file" class="file-input" id="camera-file" accept="image/*" capture="environment"><div class="tabs mb16"><button class="${photo?.source==='screenshot'?'':'active'}" data-action="photo-source" data-source="photo">カード写真</button><button class="${photo?.source==='screenshot'?'active':''}" data-action="photo-source" data-source="screenshot">スクリーンショット</button></div>${photo?.url?`<img class="image-preview" src="${photo.url}" alt="読み取り対象の画像"><div class="row spread mt8"><small>画像は端末内で処理します</small><button class="details-link" data-action="choose-photo">画像を変更</button></div>`:`<div class="upload-zone"><div class="round-icon">${icon('camera',28)}</div><h3>写真からデッキを読み込む</h3><p>カード名を読み取り、候補を確認して登録します。</p><div class="upload-actions"><button class="btn primary" data-action="take-photo">${icon('camera',16)}撮影する</button><button class="btn" data-action="choose-photo">${icon('upload',16)}画像を選択</button></div></div>`}${ocrBusy?`<div class="mt16"><div class="row spread"><h3>日本語を読み取り中…</h3><span id="ocr-percent" class="small">準備中</span></div><div class="ocr-progress"><span id="ocr-bar" style="width:5%"></span></div><p class="photo-tip">初回は日本語辞書の準備に少し時間がかかります。</p></div>`:''}${photo?.rows?.length?`<div class="row spread mt24"><h3>読み取り結果</h3><span class="badge amber">${photo.rows.filter(r=>!r.confirmed).length}件を確認</span></div><p class="photo-tip">枚数は候補です。カードと枚数を確認し、チェックしてください。</p>${photo.rows.map((r,i)=>`<div class="review-row ${r.confirmed?'':'uncertain'}">${r.id?art(r.id):`<span class="badge amber">?</span>`}<div class="grow"><select class="field ocr-card" data-index="${i}" aria-label="読み取ったカードの修正"><option value="">候補を選択</option>${cards.map(c=>`<option value="${c.id}" ${r.id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><small>${esc(r.original||'カード名を確認')}</small></div><div class="stepper"><button data-action="ocr-count" data-index="${i}" data-delta="-1" ${r.count<=1?'disabled':''}>−</button><span>${r.count}枚</span><button class="add" data-action="ocr-count" data-index="${i}" data-delta="1" ${r.count>=4?'disabled':''}>＋</button></div><input type="checkbox" class="ocr-confirm" data-index="${i}" ${r.confirmed?'checked':''} ${r.id?'':'disabled'} aria-label="カードと枚数を確認済みにする"></div>`).join('')}<button class="btn primary full mt16" data-action="ocr-add" ${ocrBusy||photo.rows.some(r=>!r.confirmed||!r.id)?'disabled':''}>確認してデッキへ追加</button>`:''}${photo?.url&&!ocrBusy&&!photo.rows?.length?`<div class="mt16">${notice(photo.error||'画像を選択しました。読み取りを開始できます。',photo.error?'amber':'')}<button class="btn primary full mt16" data-action="read-photo">${icon('spark',15)}カード名を読み取る</button></div>`:''}<div class="mt16">${notice('読み取れるのは対応44種類のカード名です。実物は重ねず、名前が読める大きさで撮影してください。枚数・不鮮明な文字は必ず確認してください。')}</div>${photo?.text?`<details class="mt16"><summary class="small">読み取った文字を確認・修正</summary><textarea class="field text-area mt8" id="ocr-text">${esc(photo.text)}</textarea><button class="btn sm mt8" data-action="reparse-photo">この文字から候補を作る</button></details>`:''}`;}
function renderMatch(){if(!myDeck()){shell(`${pageHead('対戦する','まずは自分のデッキを登録しましょう。')}<div class="empty-state">${icon('decks',45)}<h2>デッキがまだありません</h2><p>カード一覧または写真から登録できます。</p><button class="btn primary" data-action="new-deck">デッキを作成</button></div>`);return;}
 const opponents=[...PRESETS,...saved.friends];const filtered=opponents.filter(d=>(opponentCategory==='すべて'||d.category===opponentCategory)&&(!opponentQuery||d.name.includes(opponentQuery)));const d=myDeck();
 shell(`${pageHead('対戦の準備','相手を選んで、デッキの実力を確かめよう。','','READY TO DUEL')}${comparisonId?`<div class="mb16">${notice('改良前と同じ相手・回数・先後・乱数条件で対戦します。デッキの変更による違いを比較できます。')}</div>`:''}<div class="match-layout"><section><div class="chosen-deck mb16">${miniDeck(d)}<div class="grow"><small>使用デッキ</small><h3>${esc(d.name)}</h3><span class="badge mt8">オリジナル</span></div><button class="details-link" data-action="select-my-deck">変更 ${icon('chevron',13)}</button></div><div class="panel"><div class="panel-title"><h2>相手デッキを選択</h2><span class="badge">${opponents.length}デッキ</span></div><div class="search-wrap">${icon('search',17)}<input class="field" id="opponent-search" placeholder="デッキ名で検索" value="${esc(opponentQuery)}"></div><div class="filters mt16 mb16">${['すべて','環境','大会','友達','定番'].map(c=>`<button class="filter ${opponentCategory===c?'active':''}" data-action="opponent-category" data-category="${c}">${c}</button>`).join('')}</div>${filtered.map(o=>`<div class="opponent ${selectedOpp===o.id?'active':''}" role="button" tabindex="0" data-action="select-opponent" data-id="${esc(o.id)}" aria-pressed="${selectedOpp===o.id}">${miniDeck(o)}<div class="grow"><h3>${esc(o.name)}</h3><div class="row gap8"><span class="badge ${o.category==='友達'?'purple':'green'}">${esc(o.category)}</span>${dots(o)}<small>40枚</small></div><p>${esc(o.description||'共有されたデッキ')}</p><button class="details-link" data-action="deck-detail" data-id="${esc(o.id)}">構成を見る ${icon('chevron',11)}</button></div><span class="radio">${selectedOpp===o.id?icon('check',13):''}</span></div>`).join('')}${!filtered.length?`<div class="empty-state">${icon('decks',33)}<h3>${opponentCategory==='友達'?'共有デッキがありません':'この分類のデッキは準備中です'}</h3><p class="mt8">${opponentCategory==='友達'?'友達の共有リンクやデッキリストから追加できます。':'大会・環境デッキは、出典と対応カードを確認してから追加します。'}</p><button class="btn" data-action="import-text">デッキリストを読み込む</button></div>`:''}<p class="source-note mt16">初期の相手は対応カードで作った練習用です。実際の環境・大会の強さを表すものではありません。</p></div></section><aside class="panel setup-card"><div class="eyebrow mb16">MATCH SETTINGS</div><h2 class="mb16">対戦設定</h2><div class="tabs dark-active"><button class="${mode==='auto'?'active':''}" data-action="mode" data-mode="auto">${icon('bolt',14)} 自動対戦</button><button class="${mode==='manual'?'active':''}" data-action="mode" data-mode="manual">${icon('battle',14)} 手動対戦</button></div>${mode==='auto'?`<div class="setup-line"><span>対戦回数</span><select class="field" id="match-count">${[100,500,1000,3000].map(n=>`<option value="${n}" ${count===n?'selected':''}>${fmt(n)} 回</option>`).join('')}</select></div>`:''}<div class="setup-line"><span>先攻・後攻</span><select class="field" id="match-first"><option value="random" ${first==='random'?'selected':''}>${mode==='auto'?'交互に入れ替え':'ランダム'}</option><option value="first" ${first==='first'?'selected':''}>先攻</option><option value="second" ${first==='second'?'selected':''}>後攻</option></select></div><div class="setup-line"><span>ルール</span><span class="badge">オリジナル</span></div>${mode==='auto'?`<label class="checkbox-row mt8"><input type="checkbox" id="all-opponents" ${allOpp?'checked':''}>すべての練習用デッキと対戦</label>`:`<label class="checkbox-row mt8"><input type="checkbox" id="practice-mode" ${practice?'checked':''}>練習モード（ヒント・待った）</label>`}<button class="btn primary full" data-action="start-match" ${running?'disabled':''}>${icon('play',16)}${mode==='auto'?'シミュレーション開始':'対戦をはじめる'}</button><p class="source-note mt16">${mode==='auto'?'各試合をカードの処理から実行して集計します。相手AIは非公開の手札・山札・シールドを参照しません。':'カードや行動を自分で選択し、相手はAIが操作します。マナの支払いは文明を満たす組み合わせで自動処理します。'}</p><button class="details-link mt8" data-action="about">対応カード・ルールを確認 ${icon('chevron',11)}</button></aside></div>`);
}
function combinedStats(results){const keys=['total','wins','losses','unresolved','completed','earlyCreatures'];const out=Object.fromEntries(keys.map(k=>[k,results.reduce((s,r)=>s+(r.stats[k]||0),0)]));out.rate=out.completed?out.wins/out.completed:0;out.averageTurns=out.completed?results.reduce((s,r)=>s+r.stats.averageTurns*r.stats.completed,0)/out.completed:0;out.groups=[0,1].map(i=>({count:results.reduce((s,r)=>s+r.stats.groups[i].count,0),wins:results.reduce((s,r)=>s+r.stats.groups[i].wins,0)}));out.cards={};for(const r of results)for(const[id,x]of Object.entries(r.stats.cards)){out.cards[id]||={count:0,wins:0};out.cards[id].count+=x.count;out.cards[id].wins+=x.wins;}const z=1.96,n=out.completed,p=out.rate,den=1+z*z/(n||1),center=(p+z*z/(2*(n||1)))/den,half=z*Math.sqrt(p*(1-p)/(n||1)+z*z/(4*(n||1)**2))/den;out.interval=n?[Math.max(0,center-half),Math.min(1,center+half)]:null;return out;}
function startSimulation(deck,options={}){
 if(running)return;const errors=validateDeck(deck);if(errors.length){toast(errors[0]);return;}
 const base=comparisonId?saved.history.find(r=>r.id===comparisonId):null;
 const opponents=options.opponents||(base?base.results.map(r=>r.opponent):allOpp?PRESETS:[allDecks().find(d=>d.id===selectedOpp)]);if(opponents.some(d=>!d)){toast('相手デッキを選択してください');return;}
 const n=options.count||base?.count||count,seed=options.seed??base?.seed??crypto.getRandomValues(new Uint32Array(1))[0],f=options.first||base?.first||first;
 running={completed:0,total:n*opponents.length,current:opponents[0].name,deck:clone(deck),count:n,seed,first:f,opponents:clone(opponents),baseline:base?.id||null};view='analysis';render();
 worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
 worker.onmessage=({data})=>{
  if(data.type==='progress'){if(!running)return;Object.assign(running,data);renderProgress();}
  if(data.type==='done'){
   const r=running;if(!r)return;worker.terminate();worker=null;const results=data.results.map(x=>({...x,games:undefined,samples:[...x.games.filter(g=>g.winner===0).slice(0,4),...x.games.filter(g=>g.winner===1).slice(0,4),...x.games.filter(g=>g.winner===null).slice(0,2)]}));
   activeRun={id:uid(),created:new Date().toISOString(),deck:r.deck,count:r.count,seed:r.seed,first:r.first,results,stats:combinedStats(results),baseline:r.baseline,version:ENGINE_VERSION,rules:RULE_VERSION,checkedAt:metadata.checkedAt};saved.history.unshift(activeRun);saved.history=saved.history.slice(0,16);persist();running=null;comparisonId=null;view='analysis';render();toast('対戦が完了しました');
  }
  if(data.type==='error'){running=null;worker?.terminate();worker=null;toast('対戦を実行できませんでした：'+data.message);render();}
 };
 worker.onerror=()=>{running=null;worker?.terminate();worker=null;toast('対戦処理を読み込めませんでした。再読み込みして試してください');render();};
 worker.postMessage({cards,deck:clone(deck),opponents,count:n,seed,first:f});
}
function renderProgress(){if(view!=='analysis')return;const r=running;if(!r)return;const percent=Math.round(r.completed/r.total*100);shell(`${pageHead('シミュレーション中','対戦を1戦ずつ実行しています。','','SIMULATING')}<div class="panel loading-panel"><div class="row spread"><span class="badge green"><span class="running-dot"></span>実行中</span><span class="small">オリジナル · ${cards.length}種類に対応</span></div><div class="progress-ring"></div><h2>${esc(r.deck.name)} vs ${esc(r.current)}</h2><p class="muted mt8">${fmt(r.completed)} / ${fmt(r.total)} 戦</p><div class="progress-track"><span style="width:${percent}%"></span></div><div class="row spread mt8"><small>対戦処理・集計</small><small>${percent}%</small></div>${r.stats?`<div class="stats-grid mt24"><div class="metric"><small>現在の勝率</small><strong class="green">${pct(r.stats.rate)}%</strong></div><div class="metric"><small>勝利</small><strong>${fmt(r.stats.wins)}</strong></div><div class="metric"><small>敗北</small><strong>${fmt(r.stats.losses)}</strong></div></div>`:''}<button class="btn run-cancel" data-action="cancel-run">実行を中止</button></div>`);}
function resultBar(s){return `<div class="winbar"><span class="win" style="width:${s.total?s.wins/s.total*100:0}%"></span><span class="unresolved" style="width:${s.total?s.unresolved/s.total*100:0}%"></span></div><div class="row spread mt8"><strong class="green small">${fmt(s.wins)}勝</strong><span class="small">${s.unresolved?`未決着 ${s.unresolved}戦`:''}</span><strong class="red small">${fmt(s.losses)}敗</strong></div>`;}
function insights(r){const s=r.stats,eligible=Object.entries(s.cards).filter(([,v])=>v.count>=10).sort((a,b)=>b[1].wins/b[1].count-a[1].wins/a[1].count),top=eligible[0],earlyRate=s.total?s.earlyCreatures/s.total:0;return `<div class="insight"><span class="insight-icon">${icon('bolt',17)}</span><div><h3>序盤の展開をチェック</h3><p>自分の3ターン目までにクリーチャーを召喚した対戦は ${fmt(s.earlyCreatures)} / ${fmt(s.total)}戦（${pct(earlyRate)}%）です。</p><small>${earlyRate<.8?'低コストの枚数や文明の配分を見直し、改良前後で比較できます。':'次は相手のブロッカーや除去への対応を対戦記録で確認しましょう。'}</small></div></div>${top?`<div class="insight"><span class="insight-icon">${icon('spark',17)}</span><div><h3>序盤に使ったカードと勝率</h3><p>「${esc(card(top[0]).name)}」を3ターン目までに使った${top[1].count}戦では、勝率 ${pct(top[1].wins/top[1].count)}%でした。</p><small>使用と勝利の関係を示す集計です。勝因と断定するものではありません。</small></div></div>`:''}<div class="insight"><span class="insight-icon">${icon('shield',17)}</span><div><h3>苦手な相手を掘り下げる</h3><p>${esc([...r.results].sort((a,b)=>a.stats.rate-b.stats.rate)[0]?.opponent.name)}との相性を、シールドが減った場面・除去された場面から見返せます。</p><button class="details-link mt8" data-action="sample-replay" data-run="${r.id}" data-outcome="loss">負けた対戦を見返す ${icon('chevron',12)}</button></div></div>`;}
function renderAnalysis(){if(running){renderProgress();return;}const r=activeRun||saved.history[0];if(!r){shell(`${pageHead('分析・比較','自動対戦の結果から、次の1枚を考えよう。','','PERFORMANCE')}<div class="panel empty-state">${icon('analysis',44)}<h2>最初の分析をはじめよう</h2><p>デッキと相手を選んで自動対戦すると、ここに結果が表示されます。</p><button class="btn primary" data-action="nav" data-view="battle">${icon('play',15)}対戦を準備する</button></div>`);return;}activeRun=r;const s=r.stats,before=r.baseline?saved.history.find(h=>h.id===r.baseline):null;
 shell(`${pageHead('対戦の結果','実行した対戦の記録から、デッキの強みと課題を確認。',`<button class="btn" data-action="run-export" data-id="${r.id}">${icon('download',15)}結果を書き出す</button>`,'SIMULATION REPORT')}<div class="run-layout"><section class="stack"><div class="panel"><div class="matchup"><div class="matchup-side"><strong>${esc(r.deck.name)}</strong>${miniDeck(r.deck)}</div><span class="versus">VS</span><div class="matchup-side"><strong>${esc(r.results.length>1?`${r.results.length}種類の相手`:r.results[0].opponent.name)}</strong>${miniDeck(r.results[0].opponent)}</div></div><div class="run-top mt16"><span class="row gap8"><span class="check-circle">${icon('check',13)}</span><strong>シミュレーション完了</strong></span><span class="muted">${fmt(s.total)}戦</span></div><div class="small">${r.results.length>1?'選択した相手全体の':'この相手との'}勝率</div><div class="win-number">${pct(s.rate)}<span>%</span></div>${resultBar(s)}<p class="confidence">95%信頼区間 ${s.interval?`${pct(s.interval[0])}–${pct(s.interval[1])}%`:'算出不可'} · 未決着は勝率から除外</p><div class="stats-grid"><div class="metric"><small>先攻の勝率</small><strong>${s.groups[0].count?pct(s.groups[0].wins/s.groups[0].count)+'%':'—'}</strong><small>${fmt(s.groups[0].count)}戦</small></div><div class="metric"><small>後攻の勝率</small><strong>${s.groups[1].count?pct(s.groups[1].wins/s.groups[1].count)+'%':'—'}</strong><small>${fmt(s.groups[1].count)}戦</small></div><div class="metric"><small>平均決着ターン</small><strong>${s.averageTurns.toFixed(1)}</strong><small>両者の合計ターン</small></div></div></div>${before?`<div class="panel"><div class="panel-title"><h2>改良前後の比較</h2><span class="badge green">同じ対戦条件</span></div><div class="compare-grid"><div><small>改良前 · ${esc(before.deck.name)}</small><div class="compare-rate">${pct(before.stats.rate)}%</div></div><div><small>改良後 · ${esc(r.deck.name)}</small><div class="compare-rate">${pct(s.rate)}%</div></div></div><p class="small mt16">差は ${(s.rate-before.stats.rate)*100>=0?'+':''}${((s.rate-before.stats.rate)*100).toFixed(1)} ポイント。乱数・相手・回数・先後をそろえた結果です。サンプルのばらつきも含まれます。</p><button class="details-link mt8" data-action="compare-detail" data-id="${r.id}">カードの変更内容を見る ${icon('chevron',12)}</button></div>`:''}<div class="panel"><div class="panel-title"><h2>相手別の勝率</h2><span class="small">実行結果</span></div>${r.results.map((x,i)=>`<div class="matchup-row"><span class="label">${esc(x.opponent.name)}</span><div class="bar-track"><span style="width:${x.stats.rate*100}%"></span></div><strong class="green small">${pct(x.stats.rate)}%</strong><button class="icon-btn" data-action="result-detail" data-run="${r.id}" data-index="${i}" aria-label="この相手との記録">${icon('chevron',15)}</button></div>`).join('')}</div><div class="panel"><div class="panel-title"><h2>序盤に使ったカード</h2><span class="badge">3ターン目まで</span></div><div class="table-wrap"><table><thead><tr><th>カード</th><th>使用した対戦</th><th>そのときの勝率</th></tr></thead><tbody>${Object.entries(s.cards).sort((a,b)=>b[1].count-a[1].count).map(([id,x])=>`<tr><td><button class="details-link" data-action="card-detail" data-id="${id}">${esc(card(id)?.name||id)}</button></td><td>${fmt(x.count)}戦</td><td>${pct(x.wins/x.count)}%</td></tr>`).join('')}</tbody></table></div><p class="source-note mt16">各カードを使った対戦は重複します。カード単体の効果を分離した数値ではありません。</p></div></section><aside class="stack"><div class="panel"><div class="panel-title"><h2>勝敗のポイント</h2>${icon('analysis',17)}</div>${insights(r)}<button class="btn primary full mt16" data-action="improve" data-id="${r.id}">${icon('edit',15)}デッキを改良して比較</button></div><div class="panel"><h3>対戦を見返す</h3><p class="small mt8">実際の行動とカードの処理を、順番に確認できます。</p><div class="row mt16"><button class="btn grow" data-action="sample-replay" data-run="${r.id}" data-outcome="win">勝った対戦</button><button class="btn grow" data-action="sample-replay" data-run="${r.id}" data-outcome="loss">負けた対戦</button></div></div><div class="panel"><h3>分析の条件</h3><ul class="source-list"><li>実行：${date(r.created)}</li><li>カード・制限確認：${r.checkedAt}</li><li>${esc(r.rules)}</li><li>AI：ルールベース v${r.version}</li><li>各相手 ${fmt(r.count)}戦 / ${r.first==='random'?'先後交互':r.first==='first'?'先攻固定':'後攻固定'}</li></ul><p class="source-note">このアプリ内の対戦結果です。実際の大会勝率とは区別してください。</p></div></aside></div>`);
}
function renderHistory(){shell(`${pageHead('対戦履歴','過去の結果も、改良のヒントに。','','YOUR PROGRESS')}${saved.history.length?saved.history.map(r=>`<article class="history-item" data-action="open-run" data-id="${r.id}" role="button" tabindex="0"><div class="history-rate">${pct(r.stats.rate)}<small>%</small></div><div class="grow"><h3>${esc(r.deck.name)}</h3><p>${esc(r.results.map(x=>x.opponent.name).join(' / '))}</p><div class="row gap8 mt8"><span class="badge">${fmt(r.stats.total)}戦</span><small>${date(r.created)}</small>${r.baseline?'<span class="badge green">改良版</span>':''}</div></div>${icon('chevron',18)}</article>`).join(''):`<div class="panel empty-state">${icon('history',42)}<h2>対戦の記録はまだありません</h2><p>自動対戦を実行すると、結果をこの端末に保存します。</p><button class="btn primary" data-action="nav" data-view="battle">対戦をはじめる</button></div>`}<p class="source-note mt16">最新16件をこのブラウザに保存します。各結果には代表的な対戦の再現用データを保存しています。</p>`);}
function startBattle(){const d=myDeck(),o=allDecks().find(x=>x.id===selectedOpp);if(!o){toast('相手を選択してください');return;}try{const seed=crypto.getRandomValues(new Uint32Array(1))[0];battle={state:createGame([d,o],{seed,first:first==='random'?seed%2:first==='second'?1:0}),decks:clone([d,o]),practice};battleUndo=[];selectedHand=null;view='manual';render();window.scrollTo(0,0);scheduleAI();}catch(e){toast(e.message);}}
const phaseLabel=s=>s.decision?({block:'ブロックを選択',trigger:'S・トリガー',draw:'引く枚数を選択',effect:'効果の対象を選択',search:'山札から探す',untap:'ターン終了時'}[s.decision.type]):({charge:'マナチャージ',main:'メインステップ',attack:'攻撃ステップ'}[s.phase]);
function manaHTML(p){return `<div class="mana-zone">${p.mana.map(c=>`<span class="mana-gem ${c.tapped?'used':''}" style="--civ-color:${color[card(c).civ]}" title="${esc(card(c).name)}${c.tapped?'（使用済み）':''}">${card(c).cost}</span>`).join('')||'<small>0</small>'}</div>`;}
function battlefieldHTML(s,{interactive=true}={}){const mine=s.players[0],them=s.players[1],actions=getLegalActions(s);const human=actions[0]?.player===0;
 const resources=(p,who)=>`<div class="zone-row"><div class="zone-stack"><div class="backs">${p.shields.map(()=>'<span class="card-back"></span>').join('')||'<small>なし</small>'}</div><small>シールド ${p.shields.length}</small></div><div class="zone-stack"><span class="card-back"></span><small>山札 ${p.deck.length}</small></div><button class="zone-stack" style="background:none;border:0;color:inherit;padding:0" ${interactive?`data-action="zone-detail" data-player="${who}" data-zone="mana"`:''} aria-label="マナの詳細">${manaHTML(p)}<small>マナ ${p.mana.filter(x=>!x.tapped).length} / ${p.mana.length}</small></button><button class="zone-stack" style="background:none;border:0;color:inherit;padding:0" ${interactive?`data-action="zone-detail" data-player="${who}" data-zone="grave"`:''}><small style="font-size:16px;margin-top:6px">${p.grave.length}</small><small>墓地</small></button></div>`;
 const creatures=(p,who)=>`<div class="creature-row">${p.battle.map(c=>{const ready=interactive&&human&&who===0&&actions.some(a=>a.kind==='attack'&&a.uid===c.uid);return `<button class="creature-button ${c.tapped?'tapped':''} ${ready?'ready':''}" ${interactive?`data-action="battle-card" data-uid="${c.uid}" data-player="${who}"`:''} aria-label="${esc(card(c).name)}${ready?'で攻撃できる':''}">${art(c.cardId)}${c.entered===s.turn?'<span class="summon-sick">召喚したターン</span>':''}</button>`;}).join('')||'<span class="empty-zone">クリーチャーはいません</span>'}</div>`;
 return `<div class="battlefield"><div class="player-zone"><div class="player-label"><span>${icon('shield',14)} ${esc(them.name)}</span><span class="small">手札 ${them.hand.length}枚（非公開）</span></div>${resources(them,1)}</div><div class="battle-middle"><div class="battle-middle-label">相手のバトルゾーン</div>${creatures(them,1)}<div class="battle-middle-label">自分のバトルゾーン</div>${creatures(mine,0)}</div><div class="player-zone mine"><div class="player-label"><span>${icon('shield',14)} ${esc(mine.name)}</span><span class="small">${mine.turns}ターン目</span></div>${resources(mine,0)}</div><div class="battle-hand">${mine.hand.map(c=>`<button class="hand-card ${selectedHand===c.uid?'selected':''}" ${interactive?`data-action="hand-card" data-uid="${c.uid}"`:''} aria-label="手札の${esc(card(c).name)}">${art(c.cardId)}<span class="hand-label">${esc(card(c).name)}</span></button>`).join('')||'<span class="empty-zone">手札はありません</span>'}</div></div>`;
}
function renderManual(){if(!battle){view='battle';render();return;}const s=battle.state,acts=getLegalActions(s),human=acts[0]?.player===0,sel=s.players[0].hand.find(c=>c.uid===selectedHand);let actionHTML='';
 if(s.winner!==null)actionHTML=`<h2>${s.winner===0?'勝利！':'対戦終了'}</h2><p class="small mt8">${esc(s.reason)}</p><div class="row mt16"><button class="btn primary" data-action="battle-again">もう一度対戦</button><button class="btn" data-action="manual-replay">記録を見返す</button></div>`;
 else if(!human)actionHTML=`<div class="row"><span class="running-dot"></span><p>相手AIが行動しています…</p></div>`;
 else if(s.decision)actionHTML=`<p><strong>${phaseLabel(s)}</strong> · 自分で選択してください</p><div class="action-picker">${acts.map(a=>`<button class="btn ${['useTrigger','block'].includes(a.kind)?'soft':''}" data-action="battle-step" data-index="${a.id}">${esc(a.label)}</button>`).join('')}</div>`;
 else if(s.phase==='charge')actionHTML=`<p>${sel?`<strong>${esc(card(sel).name)}</strong> をマナに置きますか？`:'マナに置くカードを手札から選んでください。'}</p><div class="battle-action-grid"><button class="btn primary" data-action="battle-step" data-index="${acts.find(a=>a.kind==='charge'&&a.uid===selectedHand)?.id}" ${sel?'':'disabled'}>${icon('bolt',15)}マナに置く</button><button class="btn" data-action="battle-step" data-index="${acts.find(a=>a.kind==='skipCharge').id}">置かずに進む</button></div>`;
 else if(s.phase==='main'){const play=acts.find(a=>a.kind==='play'&&a.uid===selectedHand);actionHTML=`<p>${sel?`${esc(card(sel).name)}${play?'を使えます。':'は現在のマナでは使えません。'}`:'手札のカードを選んで、召喚・呪文を使おう。'}</p><div class="battle-action-grid"><button class="btn primary" data-action="battle-step" data-index="${play?.id}" ${play?'':'disabled'}>${icon('spark',15)}${sel&&card(sel).type==='spell'?'呪文を使う':'召喚'}</button><button class="btn" data-action="battle-step" data-index="${acts.find(a=>a.kind==='toAttack').id}">攻撃へ進む ${icon('chevron',14)}</button></div><p class="source-note mt8">必要な文明のマナを含め、支払いは自動で行います。</p>`;}
 else{const end=acts.find(a=>a.kind==='endTurn');actionHTML=`<p>${acts.some(a=>a.kind==='attack')?'緑の枠のクリーチャーを選んで攻撃できます。':'攻撃できるクリーチャーはいません。'}</p><div class="battle-action-grid"><button class="btn primary" data-action="choose-attacker" ${acts.some(a=>a.kind==='attack')?'':'disabled'}>${icon('battle',15)}攻撃する</button><button class="btn" data-action="battle-step" data-index="${end?.id}" ${end?'':'disabled'}>ターン終了 ${icon('chevron',14)}</button></div>${!end?'<p class="source-note mt8">攻撃が必要なクリーチャーがいます。</p>':''}`;}
 shell(`${pageHead('手動対戦','手札と場を見ながら、自分の一手を選ぼう。',`<button class="btn" data-action="leave-battle">${icon('close',13)}対戦を終了</button>`,'PLAY & LEARN')}<div class="battle-layout"><section><div class="battle-status"><span class="turn-pill">${s.winner!==null?'対戦終了':s.active===0?'自分のターン':'相手のターン'}</span><span class="small">${phaseLabel(s)||''} · ターン ${s.turn}</span><span class="badge">${battle.practice?'練習':'通常'}</span></div>${battlefieldHTML(s)}<div class="battle-actions">${actionHTML}${battle.practice&&s.winner===null?`<div class="battle-footer"><button class="btn ghost" data-action="battle-hint" ${human?'':'disabled'}>${icon('help',14)}ヒント</button><button class="btn ghost" data-action="undo-battle" ${battleUndo.length?'':'disabled'}>${icon('history',14)}待った</button></div>`:''}</div><p class="source-note mt16">相手の手札・山札・両者のシールドの内容は公開しません。カード画像は識別補助用です。</p></section><aside class="panel log-panel"><div class="panel-title"><h2 class="live-log-title">${icon('history',16)}対戦ログ</h2><span class="small">最新20件</span></div>${s.log.slice(-20).reverse().map(e=>`<div class="log-line ${['break','trigger','finish'].includes(e.type)?'important':''}"><strong>T${e.turn} · ${e.player===0?'自分':'相手'}</strong>${esc(e.text)}</div>`).join('')}</aside></div>`);
}
function humanAction(i){if(!battle)return;const s=battle.state,a=getLegalActions(s)[Number(i)];if(!a||a.player!==0)return;if(battle.practice){battleUndo.push(clone(s));battleUndo=battleUndo.slice(-20);}step(s,a);selectedHand=null;closeDialog();render();scheduleAI();}
function scheduleAI(){clearTimeout(battleTimer);if(!battle||battle.state.winner!==null)return;const opts=getLegalActions(battle.state);if(opts[0]?.player===1){battleTimer=setTimeout(()=>{if(!battle||view!=='manual')return;const a=chooseAI(battle.state);if(a?.player===1)step(battle.state,a);render();scheduleAI();},360);}}
function openReplay(run,result,sample){const s=runGame([run.deck,result.opponent],{seed:sample.seed,first:sample.first});replayData={state:s,title:`${run.deck.name} vs ${result.opponent.name}`,fromRun:run.id};replayIndex=0;view='replay';render();}
function renderReplay(){if(!replayData){view='analysis';render();return;}const s=replayData.state;const events=s.log;const focus=events[replayIndex];shell(`${pageHead('対戦リプレイ',esc(replayData.title),`<button class="btn" data-action="nav" data-view="analysis">${icon('back',14)}分析へ</button>`,'MATCH RECORD')}<div class="panel"><div class="row spread mb16"><span class="badge green">${s.winner===0?'自分の勝利':s.winner===1?'相手の勝利':'未決着'}</span><small>${events.length}件の行動・処理</small></div><div class="replay-steps"><button class="btn sm" data-action="replay-step" data-delta="-1" ${replayIndex===0?'disabled':''}>${icon('back',14)}</button><button class="btn sm" data-action="replay-play" aria-label="${replayTimer?'一時停止':'再生'}">${icon(replayTimer?'pause':'play',14)}</button><input type="range" id="replay-range" min="0" max="${events.length-1}" value="${replayIndex}" aria-label="対戦記録の位置"><button class="btn sm" data-action="replay-step" data-delta="1" ${replayIndex===events.length-1?'disabled':''}>${icon('chevron',14)}</button></div><div class="notice"><span class="badge">T${focus?.turn}</span><div><strong>${focus?.player===0?'自分':'相手'}：${esc(focus?.text)}</strong><div class="small">${replayIndex+1} / ${events.length}</div></div></div><div class="replay-list mt16" id="replay-list">${events.map((e,i)=>`<div class="replay-event ${i===replayIndex?'highlight':''}" data-action="replay-jump" data-index="${i}" role="button" tabindex="0"><span class="event-turn">T${e.turn} · ${e.player===0?'自分':'相手'}</span><span>${esc(e.text)}</span>${['break','trigger','finish'].includes(e.type)?`<span class="badge green">${e.type==='break'?'ブレイク':e.type==='trigger'?'S・トリガー':'決着'}</span>`:''}</div>`).join('')}</div></div><div class="mt16">${notice('カードの使用、ブロック、除去、シールドの変化を実際の処理順に表示しています。別の行動との再シミュレーションは今後の対応です。')}</div>`);if(replayIndex)$('#replay-list .highlight')?.scrollIntoView({block:'nearest',behavior:'instant'});}
function render(){if(view==='editor')renderEditor();else if(view==='battle')renderMatch();else if(view==='analysis')renderAnalysis();else if(view==='history')renderHistory();else if(view==='manual')renderManual();else if(view==='replay')renderReplay();else renderDecks();}
function norm(s){return String(s).normalize('NFKC').toLowerCase().replace(/[\s・･「」『』《》ー\-―_!！?？。、,:：/\\()（）]/g,'');}
function parseOCR(text){return parseCandidates(text,cards);}
async function processPhoto(file){if(!file)return;if(!/^image\//.test(file.type)){toast('画像ファイルを選択してください');return;}if(file.size>15*1024*1024){toast('15MB以下の画像を選択してください');return;}if(photo?.url)URL.revokeObjectURL(photo.url);photo={url:URL.createObjectURL(file),file,source:photo?.source||'photo',rows:[],text:''};render();await readPhoto();}
async function readPhoto(){if(ocrBusy||!photo?.file)return;const current=photo;ocrBusy=true;current.error=null;render();
 try{
  if(!globalThis.Tesseract){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/tesseract.min.js';script.onload=resolve;script.onerror=reject;document.head.append(script);});}
  if(!ocrWorker){ocrPromise||=globalThis.Tesseract.createWorker('jpn',1,{workerPath:new URL('vendor/worker.min.js',location.href).href,corePath:new URL('vendor/',location.href).href,langPath:new URL('vendor/',location.href).href,logger:m=>{const el=$('#ocr-percent'),bar=$('#ocr-bar');if(el)el.textContent=m.status==='recognizing text'?Math.round(m.progress*100)+'%':'準備中';if(bar)bar.style.width=(m.progress||.05)*100+'%';}});ocrWorker=await ocrPromise;}
  const result=await ocrWorker.recognize(current.file);if(photo!==current)return;current.text=result.data.text||'';current.rows=parseOCR(current.text);if(!current.rows.length)current.error='対応カードの名前を見つけられませんでした。名前が大きく写った画像で再度試すか、読み取った文字を修正してください。';
 }catch{if(photo===current)current.error='読み取りを開始できませんでした。ブラウザを更新して再度お試しください。カード一覧やリスト入力でも登録できます。';ocrPromise=null;ocrWorker=null;}
 finally{ocrBusy=false;if(view==='editor'&&editTab==='photo')render();}
}
function updateQuantity(id,delta){if(!edit)return;const c=card(id);if(!c)return;let row=edit.cards.find(r=>r.id===id);if(!row){if(delta<0||sum(edit)>=40)return;row={id,count:0};edit.cards.push(row);}if(delta>0&&(row.count>=c.limit||sum(edit)>=40)){toast('上限に達しています');return;}row.count=Math.max(0,Math.min(c.limit,row.count+delta));edit.cards=edit.cards.filter(r=>r.count>0);render();}
function saveDeck(){if(!edit)return;const e=validateDeck(edit);if(e.length){toast(e[0]);return;}edit.name=edit.name.trim()||'名前のないデッキ';edit.updated=new Date().toISOString();const i=saved.decks.findIndex(d=>d.id===edit.id);if(i>=0)saved.decks[i]=clone(edit);else saved.decks.push(clone(edit));saved.selected=edit.id;persist();edit=null;view=comparisonId?'battle':'decks';render();toast('デッキを保存しました');}
function showCard(id){const c=card(id);if(!c)return;showDialog(c.name,`<div class="card-detail-layout">${art(id)}<div><span class="badge green">対戦処理 対応済み</span><div class="card-properties"><span class="badge">${c.civ}</span><span class="badge">コスト ${c.cost}</span><span class="badge">${c.type==='creature'?'クリーチャー':'呪文'}</span>${c.power?`<span class="badge">パワー ${fmt(c.power)}</span>`:''}</div><small>${esc(c.race)}</small><p class="card-detail-text">${esc(c.text)}</p></div></div><p class="source-note mt16">カード情報確認：${metadata.checkedAt} · この版では同名${c.limit}枚まで</p><a class="details-link mt8" href="${c.source}" target="_blank" rel="noopener">公式のカード情報を開く ↗</a>`);}
function showDeck(d){if(!d)return;showDialog(d.name,`<div class="row spread mb16"><span class="badge">オリジナル</span><span class="small">${sum(d)}枚 · ${d.cards.length}種類</span></div>${d.description?`<p class="small mb16">${esc(d.description)}</p>`:''}${d.cards.filter(r=>card(r.id)).sort((a,b)=>card(a.id).cost-card(b.id).cost).map(r=>`<div class="deck-detail-row">${art(r.id)}<div class="grow"><strong>${esc(card(r.id).name)}</strong><div class="small">${card(r.id).civ} · コスト${card(r.id).cost}</div></div><strong>${r.count}枚</strong></div>`).join('')}`,`<button class="btn" data-action="export-deck" data-id="${esc(d.id)}">${icon('download',14)}書き出す</button><button class="btn primary" data-action="copy-to-mine" data-id="${esc(d.id)}">自分用にコピー</button>`);}
function download(filename,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showImport(){showDialog('デッキリストを読み込む',`<p class="small mb16">1行にカード名と枚数を入力するか、書き出したJSONを読み込めます。現在の対応は44種類です。</p><textarea class="field text-area" id="import-text" placeholder="4 凶戦士ブレイズ・クロー&#10;4 青銅の鎧&#10;…"></textarea><div class="row spread mt16"><label class="btn sm" for="json-file">${icon('upload',13)}JSONを選択</label><input type="file" class="file-input" id="json-file" accept=".json,application/json"><label class="checkbox-row"><input type="checkbox" id="import-as-friend">友達の相手デッキとして登録</label></div><p id="import-error" class="error-text"></p>`,`<button class="btn" data-action="close-dialog">キャンセル</button><button class="btn primary" data-action="apply-import">リストを読み込む</button>`);}
function parseDeckText(text){let decoded;try{decoded=JSON.parse(text);}catch{}if(decoded){const d=decoded.deck||decoded;const errors=validateDeck(d);if(errors.length)throw Error(errors.join(' / '));return {id:uid(),name:String(d.name||'読み込んだデッキ').slice(0,50),cards:d.cards.map(r=>({id:r.id,count:r.count})),format:'original',category:'自分',created:new Date().toISOString()};}
 const rows=new Map(),unknown=[];for(const line of text.split('\n')){if(!line.trim())continue;const n=norm(line),c=cards.find(c=>n.includes(norm(c.name)));if(!c){unknown.push(line.trim());continue;}const m=line.match(/^\s*([1-4])\s+/)||line.match(/(?:[×x✕]\s*|\s)([1-4])\s*(?:枚)?\s*$/);if(!m)throw Error(`${c.name}の枚数を「4 カード名」のように指定してください`);rows.set(c.id,(rows.get(c.id)||0)+Number(m[1]));}if(unknown.length)throw Error(`未対応または不明なカード：${unknown.slice(0,3).join('、')}`);if(!rows.size)throw Error('カード名と枚数を入力してください');return {id:uid(),name:'読み込んだデッキ',cards:[...rows].map(([id,count])=>({id,count})),format:'original',category:'自分',created:new Date().toISOString()};}
function showAbout(){showDialog('この版の対応範囲',`<div class="notice"><span class="badge green">v0.1</span><div><strong>紙のデュエマ · オリジナルの練習版</strong><br>公式ルールを基に、初期カード44種類の能力を個別に実装しています。全カード・全裁定への対応を保証する版ではありません。</div></div><h3 class="mt24">使える機能</h3><ul class="note-list"><li>一覧からのデッキ編集・保存・書き出し・共有リンク</li><li>写真・スクリーンショットの端末内OCRと確認</li><li>ルールベースAIとの手動・自動対戦</li><li>勝率・先後・序盤のカード使用・対戦ログの集計</li><li>改良前後を同じ相手・乱数・回数で比較</li></ul><h3 class="mt16">これから対応するもの</h3><p class="small mt8">全カード、アドバンス、環境・大会デッキ、オンライン対人戦、アカウント間の同期、一般公開のデッキ投稿、別の行動を選んだ分岐の比較。</p><h3 class="mt24">データとルール</h3><ul class="source-list"><li><a href="https://dm.takaratomy.co.jp/rule/rulechange/" target="_blank" rel="noopener">公式総合ルール Ver.1.53（2026/10/15） ↗</a></li><li><a href="https://dm.takaratomy.co.jp/rule/regulation/" target="_blank" rel="noopener">殿堂レギュレーション（確認 ${metadata.checkedAt}） ↗</a></li><li><a href="https://dm.takaratomy.co.jp/card/" target="_blank" rel="noopener">カード情報：タカラトミー公式カード検索 ↗</a></li></ul><p class="source-note mt16">非公式の練習アプリです。カードのイラストは識別補助用に生成したオリジナルです。保存先はこの端末のブラウザです。写真はOCR処理のために外部サーバーへ送信しません。共有リンクにはデッキ構成が含まれ、リンクを知っている人が読み取れます。</p><p class="source-note mt16">OCR：Tesseract.js（Apache-2.0）。<a href="vendor/TESSERACT-LICENSE.md" target="_blank">ライセンス</a></p>`);}
function showDeckMenu(d){if(!d)return;showDialog(d.name,`<div class="stack"><button class="btn" data-action="edit" data-id="${d.id}">${icon('edit',16)}デッキを編集</button><button class="btn" data-action="clone-deck" data-id="${d.id}">${icon('copy',16)}コピーを作成</button><button class="btn" data-action="share-deck" data-id="${d.id}">${icon('share',16)}共有リンクを作成</button><button class="btn" data-action="export-deck" data-id="${d.id}">${icon('download',16)}JSONで書き出す</button><button class="btn danger" data-action="confirm-delete" data-id="${d.id}">${icon('trash',16)}削除する</button></div>`);}
function sharedURL(d){const payload={name:d.name,cards:d.cards,format:'original'};const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return location.origin+location.pathname+'#deck='+encodeURIComponent(btoa(binary));}
function shareDeck(d){if(!d)return;const url=sharedURL(d);showDialog('デッキの共有',`<p class="small">このリンクを知っている人は、デッキ構成を見て読み込めます。送る相手を確認してから共有してください。</p><div class="link-box" id="shared-link">${esc(url)}</div>`,`<button class="btn primary" data-action="copy-share" data-id="${d.id}">${icon('copy',14)}リンクをコピー</button>`);}
function selectDeckDialog(){showDialog('使用するデッキ',saved.decks.map(d=>`<button class="opponent ${saved.selected===d.id?'active':''}" data-action="pick-my-deck" data-id="${esc(d.id)}">${miniDeck(d)}<div class="grow"><h3>${esc(d.name)}</h3><small>${sum(d)}枚</small></div>${icon('chevron',15)}</button>`).join(''));}
function selectActions(actions,title='行動を選択'){showDialog(title,`<div class="stack">${actions.map(a=>`<button class="btn" data-action="battle-step" data-index="${a.id}">${esc(a.label)}</button>`).join('')}</div>`);}
function showResultDetail(run,index){const r=run.results[index];showDialog(r.opponent.name,`<div class="win-number" style="font-size:54px">${pct(r.stats.rate)}<span>%</span></div>${resultBar(r.stats)}<h3 class="mt24">実際の対戦記録</h3><p class="small mt8">代表的な勝ち・負けの対戦を最大8戦保存しています。</p>${r.samples.map((s,i)=>`<button class="opponent mt8" data-action="open-sample" data-run="${run.id}" data-result="${index}" data-sample="${i}"><span class="badge ${s.winner===0?'green':''}">${s.winner===0?'勝ち':s.winner===1?'負け':'未決着'}</span><div class="grow"><h3>${s.first===0?'先攻':'後攻'} · ${s.turns}ターン</h3><p>${esc(s.reason)}</p></div>${icon('chevron',15)}</button>`).join('')}`);}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;const d=allDecks().find(x=>x.id===id),r=saved.history.find(x=>x.id===id),a=Number(el.dataset.index);
 try{
 if(action==='close-dialog')closeDialog();
 else if(action==='nav'){
  if(view==='editor'&&edit){showDialog('編集を終了しますか？','<p class="small">保存していない変更は破棄されます。編集中のデッキを残す場合は、この画面を閉じて保存してください。</p>',`<button class="btn" data-action="close-dialog">編集を続ける</button><button class="btn primary" data-action="discard-edit" data-view="${el.dataset.view}">破棄して移動</button>`);return;}
  view=el.dataset.view;clearInterval(replayTimer);replayTimer=null;clearTimeout(battleTimer);render();window.scrollTo(0,0);
 }
 else if(action==='discard-edit'){edit=null;photo=null;comparisonId=null;view=el.dataset.view;closeDialog();render();}
 else if(action==='about')showAbout();
 else if(action==='new-deck')startEdit();
 else if(action==='edit'){closeDialog();startEdit(d);}
 else if(action==='deck-menu')showDeckMenu(d);
 else if(action==='quantity')updateQuantity(id,Number(el.dataset.delta));
 else if(action==='civ'){civ=el.dataset.civ;page=0;render();}
 else if(action==='page'){page+=Number(el.dataset.delta);render();}
 else if(action==='editor-tab'){editTab=el.dataset.tab;render();}
 else if(action==='save-deck')saveDeck();
 else if(action==='use-deck'){saved.selected=id;comparisonId=null;persist();view='battle';render();window.scrollTo(0,0);}
 else if(action==='select-my-deck')selectDeckDialog();
 else if(action==='pick-my-deck'){saved.selected=id;persist();closeDialog();render();}
 else if(action==='deck-detail')showDeck(d);
 else if(action==='card-detail')showCard(id);
 else if(action==='copy-to-mine'||action==='clone-deck'){closeDialog();startEdit({...clone(d),id:uid(),name:d.name+' コピー',category:'自分'});}
 else if(action==='export-deck'){download((d?.name||'deck')+'.json',JSON.stringify({version:1,deck:d},null,2));toast('デッキを書き出しました');}
 else if(action==='share-deck')shareDeck(d);
 else if(action==='copy-share'){try{await navigator.clipboard.writeText(sharedURL(d));toast('共有リンクをコピーしました');}catch{toast('リンクを選択してコピーしてください');}}
 else if(action==='confirm-delete')showDialog('デッキを削除しますか？',`<p class="small">「${esc(d.name)}」をこの端末から削除します。対戦履歴は残ります。</p>`,`<button class="btn" data-action="close-dialog">キャンセル</button><button class="btn danger" data-action="delete-deck" data-id="${id}">削除する</button>`);
 else if(action==='delete-deck'){saved.decks=saved.decks.filter(x=>x.id!==id);if(saved.selected===id)saved.selected=saved.decks[0]?.id;persist();closeDialog();render();toast('デッキを削除しました');}
 else if(action==='import-text')showImport();
 else if(action==='apply-import'){
  try{const deck=parseDeckText($('#import-text').value);const friend=$('#import-as-friend').checked;if(friend){const errors=validateDeck(deck);if(errors.length)throw Error(errors[0]);deck.category='友達';saved.friends.push(deck);persist();closeDialog();toast('友達のデッキを登録しました');render();}else{closeDialog();startEdit(deck);}}catch(e){$('#import-error').textContent=e.message;}
 }
 else if(action==='take-photo')$('#camera-file').click();
 else if(action==='choose-photo')$('#photo-file').click();
 else if(action==='photo-source'){photo||={};photo.source=el.dataset.source;render();}
 else if(action==='read-photo')await readPhoto();
 else if(action==='ocr-count'){const row=photo.rows[a];row.count=Math.min(4,Math.max(1,row.count+Number(el.dataset.delta)));row.confirmed=false;render();}
 else if(action==='reparse-photo'){photo.text=$('#ocr-text').value;photo.rows=parseOCR(photo.text);photo.error=photo.rows.length?null:'対応カード名が見つかりませんでした。';render();}
 else if(action==='ocr-add'){
  const merged=clone(edit.cards);for(const row of photo.rows){if(!row.confirmed||!card(row.id))throw Error('すべての候補を確認してください');const old=merged.find(r=>r.id===row.id);if(old)old.count+=row.count;else merged.push({id:row.id,count:row.count});}
  const bad=merged.find(r=>r.count>card(r.id).limit);if(bad){toast(`${card(bad.id).name}が上限を超えます。既存の枚数と候補を確認してください`);return;}if(sum({cards:merged})>40){toast('合計が40枚を超えます。追加枚数を修正してください');return;}edit.cards=merged;photo=null;editTab='cards';render();toast('確認したカードを追加しました');
 }
 else if(action==='opponent-category'){opponentCategory=el.dataset.category;render();}
 else if(action==='select-opponent'){selectedOpp=id;render();}
 else if(action==='mode'){mode=el.dataset.mode;render();}
 else if(action==='start-match'){if(mode==='manual')startBattle();else startSimulation(myDeck());}
 else if(action==='cancel-run'){worker?.terminate();worker=null;running=null;render();toast('シミュレーションを中止しました');}
 else if(action==='open-run'){activeRun=r;view='analysis';render();window.scrollTo(0,0);}
 else if(action==='run-export')download('対戦結果-'+date(r.created).replace(/[\/: ]/g,'-')+'.json',JSON.stringify(r,null,2));
 else if(action==='improve'){comparisonId=r.id;mode='auto';count=r.count;first=r.first;allOpp=r.results.length>1;selectedOpp=r.results[0].opponent.id;startEdit({...clone(r.deck),id:uid(),name:r.deck.name+' 改良版',category:'自分'});toast('カードを入れ替えて保存すると、同じ条件で比較できます');}
 else if(action==='compare-detail'){
  const before=saved.history.find(x=>x.id===r.baseline);const ids=[...new Set([...before.deck.cards,...r.deck.cards].map(x=>x.id))];showDialog('カードの変更内容',ids.map(id=>({id,b:before.deck.cards.find(x=>x.id===id)?.count||0,a:r.deck.cards.find(x=>x.id===id)?.count||0})).filter(x=>x.a!==x.b).map(x=>`<div class="deck-list-row"><span class="grow">${esc(card(x.id).name)}</span><span>${x.b} → ${x.a}枚</span></div>`).join('')||'<p class="small">カードの構成は同じです。</p>');
 }
 else if(action==='result-detail')showResultDetail(saved.history.find(x=>x.id===el.dataset.run),a);
 else if(action==='sample-replay'){const run=saved.history.find(x=>x.id===el.dataset.run),winner=el.dataset.outcome==='win'?0:1;const result=run.results.find(x=>x.samples.some(s=>s.winner===winner));if(!result){toast('該当する対戦記録がありません');return;}openReplay(run,result,result.samples.find(s=>s.winner===winner));}
 else if(action==='open-sample'){const run=saved.history.find(x=>x.id===el.dataset.run),result=run.results[Number(el.dataset.result)];closeDialog();openReplay(run,result,result.samples[Number(el.dataset.sample)]);}
 else if(action==='hand-card'){selectedHand=el.dataset.uid;render();}
 else if(action==='battle-card'){const uid=el.dataset.uid,actions=getLegalActions(battle.state).filter(a=>a.player===0&&a.kind==='attack'&&a.uid===uid);if(actions.length)selectActions(actions,'攻撃先を選択');else{const c=battle.state.players[Number(el.dataset.player)].battle.find(x=>x.uid===uid);if(c)showCard(c.cardId);}}
 else if(action==='choose-attacker')selectActions(getLegalActions(battle.state).filter(a=>a.player===0&&a.kind==='attack'),'攻撃するクリーチャーと対象');
 else if(action==='battle-step')humanAction(a);
 else if(action==='battle-hint'){const hint=chooseAI(battle.state);if(hint?.player===0)showDialog('次の一手のヒント',`<div class="notice"><span class="insight-icon">${icon('spark',20)}</span><div><strong>${esc(hint.label)}</strong><p class="small mt8">公開情報と自分の手札から選んだ、ルールベースAIの候補です。最善手を保証するものではありません。</p></div></div>`,`<button class="btn" data-action="close-dialog">自分で選ぶ</button><button class="btn primary" data-action="battle-step" data-index="${hint.id}">この行動を選ぶ</button>`);}
 else if(action==='undo-battle'){clearTimeout(battleTimer);if(battleUndo.length){battle.state=battleUndo.pop();selectedHand=null;render();scheduleAI();}}
 else if(action==='zone-detail'){const p=battle.state.players[Number(el.dataset.player)],zone=el.dataset.zone;showDialog(zone==='mana'?'マナゾーン':'墓地',p[zone].map(c=>`<div class="deck-detail-row">${art(c.cardId)}<div class="grow"><strong>${esc(card(c).name)}</strong><div class="small">${card(c).civ} / ${zone==='mana'?(c.tapped?'使用済み':'使用可能'):''}</div></div></div>`).join('')||'<p class="small">カードはありません。</p>');}
 else if(action==='leave-battle')showDialog('対戦を終了しますか？','<p class="small">現在の対戦は保存されません。</p>',`<button class="btn" data-action="close-dialog">対戦を続ける</button><button class="btn primary" data-action="end-battle">終了する</button>`);
 else if(action==='end-battle'){clearTimeout(battleTimer);battle=null;closeDialog();view='battle';render();}
 else if(action==='battle-again')startBattle();
 else if(action==='manual-replay'){replayData={state:clone(battle.state),title:battle.decks.map(d=>d.name).join(' vs ')};replayIndex=0;view='replay';render();}
 else if(action==='replay-step'){replayIndex=Math.max(0,Math.min(replayData.state.log.length-1,replayIndex+Number(el.dataset.delta)));render();}
 else if(action==='replay-jump'){replayIndex=a;render();}
 else if(action==='replay-play'){if(replayTimer){clearInterval(replayTimer);replayTimer=null;render();}else{if(replayIndex===replayData.state.log.length-1)replayIndex=0;replayTimer=setInterval(()=>{if(view!=='replay'){clearInterval(replayTimer);replayTimer=null;return;}if(replayIndex<replayData.state.log.length-1)replayIndex++;else{clearInterval(replayTimer);replayTimer=null;}render();},700);render();}}
 }catch(e){toast(e.message||'操作を完了できませんでした');console.error(e);}
});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='deck-name'&&edit){edit.name=e.value;return;}if(e.id==='card-search'||e.id==='opponent-search'){const caret=e.selectionStart;if(e.id==='card-search'){query=e.value;page=0;}else opponentQuery=e.value;render();const replacement=$('#'+e.id);replacement?.focus();replacement?.setSelectionRange(caret,caret);}if(e.id==='replay-range'){replayIndex=Number(e.value);render();}});
document.addEventListener('change',async event=>{const e=event.target;
 if(e.id==='cost-filter'){costFilter=e.value;page=0;render();}if(e.id==='type-filter'){typeFilter=e.value;page=0;render();}
 if(e.id==='match-count')count=Number(e.value);if(e.id==='match-first')first=e.value;if(e.id==='all-opponents')allOpp=e.checked;if(e.id==='practice-mode')practice=e.checked;
 if(e.id==='photo-file'||e.id==='camera-file')await processPhoto(e.files[0]);
 if(e.matches('.ocr-card')){const r=photo.rows[Number(e.dataset.index)];r.id=e.value;r.confirmed=false;render();}
 if(e.matches('.ocr-confirm')){photo.rows[Number(e.dataset.index)].confirmed=e.checked;render();}
 if(e.id==='json-file'&&e.files[0]){if(e.files[0].size>1024*1024){$('#import-error').textContent='1MB以下のJSONを選択してください';return;}$('#import-text').value=await e.files[0].text();}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"]')){e.preventDefault();e.target.click();}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('beforeunload',e=>{if(edit||running||(battle&&battle.state.winner===null)){e.preventDefault();e.returnValue='';}});
async function boot(){try{const r=await fetch('cards.json');if(!r.ok)throw Error('カード情報を読み込めません');metadata=await r.json();cards=metadata.cards;setCards(cards);render();
 if(location.hash.startsWith('#deck=')){try{if(location.hash.length>32768)throw Error('共有データが大きすぎます');const b=atob(decodeURIComponent(location.hash.slice(6)));const data=JSON.parse(new TextDecoder().decode(Uint8Array.from(b,c=>c.charCodeAt(0))));const d=parseDeckText(JSON.stringify(data));d.category='友達';d.description='共有リンクから読み込んだデッキです。';saved.friends.push(d);persist();history.replaceState(null,'',location.pathname);view='battle';selectedOpp=d.id;render();toast('共有されたデッキを相手一覧に追加しました');}catch{toast('共有リンクの形式が正しくないか、未対応のカードが含まれています');}}
 }catch(e){root.innerHTML=`<div class="boot"><h2>読み込みできませんでした</h2><p>${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">再読み込み</button></div>`;}}
boot();
